import assert from "node:assert/strict";
import { test } from "node:test";
import { Emitter } from "../src/emitter.ts";

test("grader: once", () => {
  const e = new Emitter();
  const seen: unknown[] = [];
  e.once("x", (p) => seen.push(p));
  e.emit("x", 1);
  e.emit("x", 2);
  assert.deepEqual(seen, [1]);
  const off = e.once("y", (p) => seen.push(p));
  off();
  e.emit("y", 3);
  assert.deepEqual(seen, [1]);
  e.on("z", (p) => seen.push(p));
  e.emit("z", 4);
  e.emit("z", 5);
  assert.deepEqual(seen, [1, 4, 5]);
});

